import { useCallback, useEffect, useRef, useState } from "react";
import { ChevronDown, ChevronRight, ExternalLink, GitPullRequest, RefreshCw, RotateCw, Server, Ticket } from "lucide-react";
import { fetchJiraSummary, fetchKafkaSummary, fetchPullRequests, restartKafkaTask, restartFailedKafkaTasks } from "./api";

const REFRESH_MS = 5 * 60 * 1000;
const RETRY_MS = 15 * 1000;
const VISIBLE_PROJECTS = 8;

/**
 * Loads one dashboard section when the page opens, then keeps it fresh.
 * Returns { data, error, loading, reload }.
 */
function useSection(fetcher) {
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const timer = useRef();
  const alive = useRef(true);

  const load = useCallback(
    async (force) => {
      clearTimeout(timer.current);
      setLoading(true);
      let delay = REFRESH_MS;
      try {
        const body = await fetcher(force);
        if (!alive.current) {
          return;
        }
        if (body?.status === "ERROR") {
          setError(body.message || "Could not load data");
          delay = RETRY_MS;
        } else {
          setData(body);
          setError(body?.stale ? body.message || "Showing the last successful load" : "");
          delay = body?.stale ? RETRY_MS : REFRESH_MS;
        }
      } catch (failure) {
        if (!alive.current) {
          return;
        }
        setError(failure instanceof Error ? failure.message : "Backend not reachable");
        delay = RETRY_MS;
      }
      setLoading(false);
      timer.current = setTimeout(() => load(false), delay);
    },
    [fetcher]
  );

  useEffect(() => {
    alive.current = true;
    load(false);
    return () => {
      alive.current = false;
      clearTimeout(timer.current);
    };
  }, [load]);

  return { data, error, loading, reload: () => load(true) };
}

function Card({ icon: Icon, title, headline, state, children, link }) {
  const { data, error, loading, reload } = state;
  return (
    <div className="context-card ctx-card">
      <div className="ctx-head">
        <div className="card-title">
          <Icon size={16} /> {title}
        </div>
        <div className="ctx-tools">
          {link && (
            <a className="vuln-icon-btn" href={link} target="_blank" rel="noopener noreferrer" title="Open in browser">
              <ExternalLink size={13} />
            </a>
          )}
          <button type="button" className="vuln-icon-btn" onClick={reload} disabled={loading} title="Reload">
            <RefreshCw size={13} className={loading ? "spin" : ""} />
          </button>
        </div>
      </div>
      {headline && data && <div className="ctx-headline">{headline}</div>}
      {loading && !data && <div className="ctx-note">Loading...</div>}
      {error && <div className={`ctx-note ${data ? "warn" : "error"}`}>{error}</div>}
      {data && children}
    </div>
  );
}

// ------------------------------------------------------------------ EMH Jira

export function JiraCard() {
  const state = useSection(fetchJiraSummary);
  const { data } = state;
  const rawStatuses = data?.statuses || [];
  const statuses = rawStatuses.filter((row) => {
    const s = (row.status || "").toLowerCase();
    return (
      !s.includes("pushed to production") &&
      !s.includes("in production") &&
      s !== "production" &&
      s !== "closed" &&
      s !== "cancelled" &&
      s !== "canceled" &&
      s !== "done" &&
      s !== "resolved" &&
      s !== "completed"
    );
  });
  const max = Math.max(1, ...statuses.map((row) => Number(row.count) || 0));
  const total = statuses.reduce((sum, row) => sum + (Number(row.count) || 0), 0);

  return (
    <Card icon={Ticket} title="EMH Jira" headline={<>Total tickets: <strong>{total}</strong></>} state={state} link={data?.url}>
      <div className="ctx-rows">
        {statuses.map((row) => (
          <div key={row.status} className="ctx-row" title={`${row.status}: ${row.count}`}>
            <span className="ctx-row-name">{row.status}</span>
            <span className="ctx-bar"><span style={{ width: `${((Number(row.count) || 0) / max) * 100}%` }} /></span>
            <strong className="ctx-row-count">{row.count}</strong>
          </div>
        ))}
        {statuses.length === 0 && <div className="ctx-note">No open EMH tickets.</div>}
      </div>
    </Card>
  );
}

// ------------------------------------------------------------------ Pull requests

export function PullRequestCard() {
  const state = useSection(fetchPullRequests);
  const { data } = state;
  const [showAll, setShowAll] = useState(false);
  const projects = data?.projects || [];
  const visible = showAll ? projects : projects.slice(0, VISIBLE_PROJECTS);

  return (
    <Card
      icon={GitPullRequest}
      title="Open Pull Requests"
      headline={<>Total open PRs: <strong>{data?.total}</strong> in {projects.length} {projects.length === 1 ? "project" : "projects"}</>}
      state={state}
    >
      <div className="ctx-rows">
        {visible.map((row) => (
          <a key={row.project} className="ctx-row ctx-link" href={row.url} target="_blank" rel="noopener noreferrer" title={`Open pull requests of ${row.project}`}>
            <span className="ctx-row-name">{row.project}</span>
            <span className="ctx-dots" />
            <strong className="ctx-row-count">{row.openPRs}</strong>
          </a>
        ))}
        {projects.length === 0 && <div className="ctx-note">No open pull requests.</div>}
      </div>
      {projects.length > VISIBLE_PROJECTS && (
        <button type="button" className="ctx-more" onClick={() => setShowAll((value) => !value)}>
          {showAll ? "Show top " + VISIBLE_PROJECTS : `Show all ${projects.length} projects`}
        </button>
      )}
    </Card>
  );
}

// ------------------------------------------------------------------ Kafka connectors

export function KafkaCard() {
  const state = useSection(fetchKafkaSummary);
  const { data } = state;
  const [open, setOpen] = useState(true);
  const [restarting, setRestarting] = useState({});
  const [actionFeedback, setActionFeedback] = useState({});
  const problems = data?.notRunning || [];

  const handleRestartTask = async (connectorName, taskId) => {
    const key = `${connectorName}-${taskId}`;
    setRestarting((prev) => ({ ...prev, [key]: true, [connectorName]: true }));
    setActionFeedback((prev) => ({ ...prev, [connectorName]: null }));
    try {
      await restartKafkaTask(connectorName, taskId);
      setActionFeedback((prev) => ({
        ...prev,
        [connectorName]: { type: "success", text: `Task ${taskId} restart triggered successfully!` }
      }));
      setTimeout(() => {
        state.reload();
      }, 1500);
    } catch (err) {
      setActionFeedback((prev) => ({
        ...prev,
        [connectorName]: { type: "error", text: err.message || `Failed to restart task ${taskId}` }
      }));
    } finally {
      setRestarting((prev) => ({ ...prev, [key]: false, [connectorName]: false }));
      setTimeout(() => {
        setActionFeedback((prev) => ({ ...prev, [connectorName]: null }));
      }, 6000);
    }
  };

  const handleRestartAll = async (row) => {
    const connectorName = row.name;
    const taskIds = row.failedTaskIds?.length
      ? row.failedTaskIds
      : (row.failedTasks || [])
          .map((t) => parseInt(String(t).replace(/\D/g, ""), 10))
          .filter((n) => !isNaN(n));

    setRestarting((prev) => ({ ...prev, [connectorName]: true }));
    setActionFeedback((prev) => ({ ...prev, [connectorName]: null }));
    try {
      if (taskIds.length > 0) {
        for (const tid of taskIds) {
          await restartKafkaTask(connectorName, tid);
        }
      } else {
        await restartFailedKafkaTasks(connectorName);
      }
      setActionFeedback((prev) => ({
        ...prev,
        [connectorName]: { type: "success", text: `Restart triggered for ${connectorName}!` }
      }));
      setTimeout(() => {
        state.reload();
      }, 1500);
    } catch (err) {
      setActionFeedback((prev) => ({
        ...prev,
        [connectorName]: { type: "error", text: err.message || "Failed to restart" }
      }));
    } finally {
      setRestarting((prev) => ({ ...prev, [connectorName]: false }));
      setTimeout(() => {
        setActionFeedback((prev) => ({ ...prev, [connectorName]: null }));
      }, 6000);
    }
  };

  return (
    <Card icon={Server} title="Kafka Connectors" headline={<>Kafka Connector: <strong>{data?.total}</strong></>} state={state}>
      <div className="kafka-chips">
        <span className="kafka-chip running">Running: {data?.running}</span>
        <span className="kafka-chip paused">Paused: {data?.paused}</span>
        <span className="kafka-chip failed">Failed: {data?.failed}</span>
        {data?.other > 0 && <span className="kafka-chip other">Other: {data.other}</span>}
      </div>
      {problems.length > 0 && (
        <>
          <button type="button" className="ctx-more" onClick={() => setOpen((value) => !value)}>
            {open ? <ChevronDown size={12} /> : <ChevronRight size={12} />} Not running ({problems.length})
          </button>
          {open && (
            <div className="ctx-rows">
              {problems.map((row) => {
                const taskIds = row.failedTaskIds?.length
                  ? row.failedTaskIds
                  : (row.failedTasks || [])
                      .map((t) => parseInt(String(t).replace(/\D/g, ""), 10))
                      .filter((n) => !isNaN(n));
                const isFailed = row.health === "FAILED" || taskIds.length > 0;
                const isConnectorRestarting = restarting[row.name];
                const feedback = actionFeedback[row.name];

                return (
                  <div key={row.name} className="kafka-problem-card" title={row.reason || ""}>
                    <div className="ctx-row">
                      <span className="ctx-row-name" title={row.name}>{row.name}</span>
                      <span className={`kafka-state ${String(row.health).toLowerCase()}`}>
                        {row.health === "FAILED" && row.failedTasks?.length
                          ? `FAILED (${row.failedTasks.join(", ")})`
                          : row.health}
                      </span>
                    </div>

                    {isFailed && taskIds.length > 0 && (
                      <div className="kafka-tasks-action-row">
                        {taskIds.map((taskId) => {
                          const taskKey = `${row.name}-${taskId}`;
                          const isTaskRestarting = restarting[taskKey] || isConnectorRestarting;
                          return (
                            <button
                              key={taskId}
                              type="button"
                              className="kafka-restart-btn"
                              disabled={isTaskRestarting}
                              onClick={() => handleRestartTask(row.name, taskId)}
                              title={`Restart failed task ${taskId} via Kafka Connect REST API`}
                            >
                              <RotateCw size={11} className={isTaskRestarting ? "spin" : ""} />
                              {isTaskRestarting ? `Restarting task ${taskId}...` : `Restart Task ${taskId}`}
                            </button>
                          );
                        })}
                      </div>
                    )}

                    {isFailed && taskIds.length === 0 && (
                      <div className="kafka-tasks-action-row">
                        <button
                          type="button"
                          className="kafka-restart-btn"
                          disabled={isConnectorRestarting}
                          onClick={() => handleRestartAll(row)}
                          title={`Restart failed connector ${row.name}`}
                        >
                          <RotateCw size={11} className={isConnectorRestarting ? "spin" : ""} />
                          {isConnectorRestarting ? "Restarting..." : "Restart"}
                        </button>
                      </div>
                    )}

                    {feedback && (
                      <div className={`kafka-feedback-msg ${feedback.type}`}>
                        {feedback.text}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}
    </Card>
  );
}
